def connect():
    conn = sqlite3.connect(DB, timeout=15)
    conn.execute('PRAGMA foreign_keys=ON')
    conn.execute('''CREATE TABLE IF NOT EXISTS students (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      full_name TEXT NOT NULL,
      roll_number TEXT NOT NULL COLLATE NOCASE UNIQUE,
      college_email TEXT NOT NULL COLLATE NOCASE UNIQUE,
      mobile TEXT,
      branch TEXT NOT NULL,
      academic_year TEXT NOT NULL CHECK(academic_year IN ('2nd Year','3rd Year','4th Year')),
      password_hash TEXT NOT NULL,
      photo_path TEXT,
      rules_accepted INTEGER NOT NULL DEFAULT 0,
      status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','APPROVED','REJECTED')),
      email_verified INTEGER NOT NULL DEFAULT 0,
      nomination_interest INTEGER NOT NULL DEFAULT 0,
      nomination_post TEXT,
      slogan TEXT,
      candidate_statement TEXT,
      relevant_experience TEXT,
      skills TEXT,
      action_plan TEXT,
      preferred_wing TEXT,
      created_at TEXT NOT NULL
    )''')
    existing = {row[1] for row in conn.execute('PRAGMA table_info(students)').fetchall()}
    migrations = [
        ('nomination_interest', 'INTEGER NOT NULL DEFAULT 0'),
        ('nomination_post', 'TEXT'), ('slogan', 'TEXT'),
        ('candidate_statement', 'TEXT'), ('relevant_experience', 'TEXT'),
        ('skills', 'TEXT'), ('action_plan', 'TEXT'), ('preferred_wing', 'TEXT')]
    for col, ddl in migrations:
        if col not in existing:
            conn.execute(f'ALTER TABLE students ADD COLUMN {col} {ddl}')
    # Voting schema is additive: existing student registrations are preserved.
    conn.executescript('''
      CREATE TABLE IF NOT EXISTS election_settings (
        id INTEGER PRIMARY KEY CHECK(id=1), election_name TEXT NOT NULL DEFAULT 'SRIJAN Elections 2026',
        is_open INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL DEFAULT ''
      );
      INSERT OR IGNORE INTO election_settings(id,election_name,is_open,updated_at)
        VALUES(1,'SRIJAN Elections 2026',0,datetime('now'));
      CREATE TABLE IF NOT EXISTS election_candidates (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        student_id INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE,
        post_name TEXT NOT NULL, display_name TEXT, tagline TEXT, card_photo_path TEXT,
        created_at TEXT NOT NULL, UNIQUE(student_id,post_name)
      );
      CREATE TABLE IF NOT EXISTS voter_sessions (
        id INTEGER PRIMARY KEY AUTOINCREMENT, session_token TEXT NOT NULL UNIQUE,
        voter_id INTEGER NOT NULL REFERENCES students(id), captured_photo_path TEXT NOT NULL,
        login_at TEXT NOT NULL, completed_posts INTEGER NOT NULL DEFAULT 0
      );
      CREATE TABLE IF NOT EXISTS voter_post_completion (
        id INTEGER PRIMARY KEY AUTOINCREMENT, voter_id INTEGER NOT NULL REFERENCES students(id),
        post_name TEXT NOT NULL, session_token TEXT NOT NULL, completed_at TEXT NOT NULL,
        captured_photo_path TEXT NOT NULL, UNIQUE(voter_id,post_name)
      );
      CREATE TABLE IF NOT EXISTS secret_ballots (
        id INTEGER PRIMARY KEY AUTOINCREMENT, ballot_code TEXT NOT NULL UNIQUE,
        post_name TEXT NOT NULL, candidate_id INTEGER NOT NULL REFERENCES election_candidates(id),
        cast_day TEXT NOT NULL
      );
      CREATE TABLE IF NOT EXISTS election_audit (
        id INTEGER PRIMARY KEY AUTOINCREMENT, student_id INTEGER REFERENCES students(id),
        action TEXT NOT NULL, post_name TEXT, details TEXT, photo_path TEXT,
        created_at TEXT NOT NULL
      );
      CREATE INDEX IF NOT EXISTS idx_ballots_post ON secret_ballots(post_name);
      CREATE INDEX IF NOT EXISTS idx_completion_voter ON voter_post_completion(voter_id);
      CREATE INDEX IF NOT EXISTS idx_audit_created ON election_audit(created_at);
    ''')
    conn.commit()
    return conn


def hash_password(password: str) -> str:
    salt = secrets.token_bytes(16)
    digest = hashlib.scrypt(password.encode(), salt=salt, n=2**14, r=8, p=1)
    return 'scrypt$' + salt.hex() + '$' + digest.hex()


def valid_email(email: str) -> bool:
    return bool(re.fullmatch(r"[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}", email.strip()))


def store_photo(upload):
    if upload is None:
        return None, None
    if upload.size > 2 * 1024 * 1024:
        return None, 'Photo must be 2 MB or smaller.'
    try:
        raw = upload.getvalue()
        original = Image.open(io.BytesIO(raw))
        fmt = original.format
        original.verify()
        if fmt not in ('JPEG', 'PNG', 'WEBP'):
            return None, 'Only JPG, PNG or WEBP images are allowed.'
        im = ImageOps.exif_transpose(Image.open(io.BytesIO(raw)))
        im.thumbnail((700, 700))
        ext = {'JPEG': '.jpg', 'PNG': '.png', 'WEBP': '.webp'}[fmt]
        if fmt == 'JPEG' and im.mode not in ('RGB', 'L'):
            im = im.convert('RGB')
        filename = secrets.token_hex(12) + ext
        path = UPLOADS / filename
        im.save(path, format=fmt, quality=90)
        return str(Path('uploads') / filename), None
    except Exception:
        return None, 'This file is not a valid image. Please upload a JPG, PNG or WEBP photo.'



