        excel_headers = ['ID','Full Name','Roll Number','College Email','Mobile','Branch','Academic Year','Applied for Post','Selected Post','Slogan','Candidate Statement','Relevant Experience','Skills','Action Plan','Preferred Wing','Photo Path','Account Status','Registered At']
        excel_rows = [tuple(r) for r in rows]
