if submitted:
    errors = []
    # Mobile number is optional. Accept a valid Indian 10-digit number with
    # common formatting (+91 prefix, spaces, or hyphens), then store only 10 digits.
    mobile_input = re.sub(r'[\s()-]', '', mobile.strip())
    if mobile_input.startswith('+91'):
        mobile_input = mobile_input[3:]
    elif mobile_input.startswith('91') and len(mobile_input) == 12:
        mobile_input = mobile_input[2:]
    normalized_mobile = mobile_input

    if len(full_name.strip()) < 2: errors.append('Enter your full name.')
    if not roll.strip(): errors.append('Enter your college roll number.')
    if not valid_email(email): errors.append('Enter a valid college email address.')
    if mobile.strip() and not re.fullmatch(r'[6-9]\d{9}', normalized_mobile):
        errors.append('Enter a valid 10-digit Indian mobile number (you may include +91, spaces, or hyphens), or leave the field blank.')
    if branch == 'Select branch': errors.append('Select your branch / department.')
    if branch == 'Other': errors.append('Please contact the administrator to add your branch before registering.')
    if year not in ('2nd Year', '3rd Year', '4th Year'): errors.append('Select your academic year.')
    if len(password) < 8: errors.append('Password must contain at least 8 characters.')
    if password != confirm: errors.append('Password and confirm password do not match.')
    if not accept: errors.append('Accept the election rules and privacy notice to continue.')
    if wants_post and selected_post not in POSTS_BY_YEAR.get(year, []): errors.append('Select a post available for your academic year.')
    if not photo: errors.append('Profile photo is required for every registration, including voters and candidates.')
    if wants_post and not slogan.strip(): errors.append('Enter a candidate slogan.')
    if wants_post and len(slogan.strip().split()) > 5: errors.append('Slogan must contain no more than five words.')
    photo_rel = None
    if not errors:
        photo_rel, photo_error = store_photo(photo)
        if photo_error: errors.append(photo_error)
    if errors:
        for error in errors: st.error(error)
    else:
        try:
            with connect() as conn:
                conn.execute(
                    '''INSERT INTO students(
                    full_name,roll_number,college_email,mobile,branch,academic_year,password_hash,photo_path,
                    rules_accepted,status,email_verified,nomination_interest,nomination_post,slogan,candidate_statement,
                    relevant_experience,skills,action_plan,preferred_wing,created_at)
                    VALUES(?,?,?,?,?,?,?,?,1,'APPROVED',0,?,?,?,?,?,?,?,?,?)''',
                    (full_name.strip(), roll.strip(), email.strip().lower(), normalized_mobile or None,
                     branch, year, hash_password(password), photo_rel, 1 if wants_post else 0,
                     selected_post if wants_post else None, slogan.strip() if wants_post else None,
                     None,
                     relevant_experience.strip() if wants_post else None, skills.strip() if wants_post else None,
                     action_plan.strip() if wants_post else None, preferred_wing if wants_post else None,
                     datetime.now().astimezone().isoformat(timespec='seconds')))
            st.session_state['election_success'] = 'Registration submitted successfully.'
            st.session_state['candidate_card_details'] = {
                'full_name': full_name.strip(), 'roll_number': roll.strip(),
                'nomination_interest': bool(wants_post),
                'nomination_post': selected_post if wants_post else None,
                'slogan': slogan.strip() if wants_post else '',
                'preferred_wing': preferred_wing if wants_post else 'General',
                'photo_path': photo_rel,
            }
            # Clear form widgets before they are rebuilt on the next run.
            st.session_state['_clear_fields_after_success'] = True
            st.session_state['photo_reset_id'] = st.session_state.get('photo_reset_id', 0) + 1
            st.rerun()
        except sqlite3.IntegrityError:
            st.error('This roll number or college email is already registered. Check your details or contact the administrator.')
        except Exception as exc:
            st.error(f'Registration could not be completed. Please try again. ({type(exc).__name__})')


